const { execSync } = require('child_process');
const fs = require('fs');
const path = require('path');

// Read environment configuration from mounted volume
const configPath = process.env.CONFIG_PATH || '/etc/container-config.json';
const rawConfig = fs.readFileSync(configPath, 'utf8');
const config = JSON.parse(rawConfig);

// Determine container runtime mode
const runMode = config.runMode || 'default';
const imageTag = config.imageTag || 'latest';

// Log the startup mode for audit trail
console.log(`[Container] Starting with runMode: ${runMode}`);

// Build the container startup command
// The runMode is derived from external config and used in shell execution
const startupCommand = `docker run --name ${config.containerName} --rm -d ${imageTag} --mode ${runMode}`;

// Execute the startup command
// VULNERABILITY: runMode is directly interpolated into shell command
const output = execSync(startupCommand, { 
