  }
  return config;
}

/**
 * 执行远程部署脚本
 * @param {string} scriptPath - 部署脚本路径
 * @param {string} targetHost - 目标主机地址
 * @param {string} authToken - 认证令牌（从环境变量注入）
 */
function runRemoteDeploy(scriptPath, targetHost, authToken) {
  // 构造远端执行命令，使用环境变量传递 token 避免直接出现在命令行
  const cmdStr = `ssh -i /home/deploy/.ssh/deploy_key deploy@${targetHost} ` +
    `'AUTH_TOKEN=${authToken} bash ${scriptPath} --env production'`;

  try {
    // 执行部署命令
    const output = execSync(cmdStr, {
      shell: true,
      timeout: 30000,
      stdio: ['pipe', 'pipe', 'pipe']
    });
    console.log(`[deploy] ${targetHost} output:`, output.toString());
    return output.toString();
  } catch (err) {
    console.error(`[deploy] Failed on ${targetHost}:`, err.message);
    throw new Error(`Deployment failed for ${targetHost}`);
  }
}

