  const hosts = config.targetHosts || ['10.0.0.1'];

  // 获取认证令牌
  const authToken = process.env.DEPLOY_AUTH_TOKEN;
  if (!authToken) {
    console.error('Missing DEPLOY_AUTH_TOKEN environment variable');
    process.exit(1);
  }

  // 逐个主机执行部署
