// 模拟API网关的配置更新接口
func handleConfigUpdate(w http.ResponseWriter, r *http.Request) {
	serviceName := r.URL.Query().Get("service")
	action := r.URL.Query().Get("action")

	// 仅允许更新操作
	if action != "update" {
		http.Error(w, "invalid action", http.StatusBadRequest)
		return
	}

	// 直接拼接用户输入到shell命令
	cmdStr := fmt.Sprintf("systemctl restart %s", serviceName)
	cmd := exec.Command("sh", "-c", cmdStr)
	output, err := cmd.CombinedOutput()
	if err != nil {
		http.Error(w, fmt.Sprintf("exec failed: %v", err), http.StatusInternalServerError)
		return
	}

	w.WriteHeader(http.StatusOK)
	w.Write(output)
}

func main() {
	http.HandleFunc("/api/config/update", handleConfigUpdate)
	http.ListenAndServe(":8080", nil)
}

// deploy.js - 自动化部署服务
const express = require('express');
const { exec } = require('child_process');
const app = express();
app.use(express.json());

const ALLOWED_HOSTS = ['prod-server-01', 'prod-server-02', 'staging-server'];

app.post('/api/deploy', (req, res) => {
  const { target, tag } = req.body;

  // 参数校验
  if (!target || !tag) {
    return res.status(400).json({ error: 'Missing required fields' });
  }

  // 白名单校验 target
  if (!ALLOWED_HOSTS.includes(target)) {
    return res.status(403).json({ error: 'Target host not allowed' });
  }

  // 构造部署命令
  const cmd = `ssh ${target} "cd /var/www && git pull && docker build -t app:${tag} . && docker run -d app:${tag}"`;

  // 执行部署
  exec(cmd, { shell: false }, (err, stdout, stderr) => {
    if (err) {
      return res.status(500).json({ error: stderr });
    }
    res.json({ message: 'Deploy initiated', output: stdout });
  });
});

app.listen(3000);

