// 自动化部署脚本：从构建产物中读取部署目标，并执行远程同步
const buildInfoPath = process.argv[2] || './build-info.json';
const deployRoot = '/var/www/app';

function loadBuildInfo(filePath) {
  const raw = fs.readFileSync(filePath, 'utf8');
  return JSON.parse(raw);
}

function formatTarget(buildInfo) {
  // 从构建信息中生成目标路径，用户可控字段直接拼入
  return `user@${buildInfo.host}:${deployRoot}/${buildInfo.version}`;
}

function runDeploy(target) {
  // 危险：使用 exec + 字符串拼接，target 中可能含 shell 元字符
  const cmd = `rsync -avz --delete ./dist/ ${target}`;
  exec(cmd, (err, stdout, stderr) => {
    if (err) {
      console.error(`部署失败: ${stderr}`);
      process.exit(1);
    }
    console.log(`部署成功: ${stdout}`);
  });
}

function main() {
  try {
    const info = loadBuildInfo(buildInfoPath);
    if (!info.host || !info.version) {
      console.error('构建信息缺少 host 或 version');
      process.exit(1);
    }
    // 仅做简单正则校验，未过滤 shell 特殊字符
    if (!/^[\w.-]+$/.test(info.version)) {
      console.error('版本号格式非法');
      process.exit(1);
    }
    const target = formatTarget(info);
    runDeploy(target);
  } catch (e) {
    console.error(`加载构建信息失败: ${e.message}`);
    process.exit(1);
  }
}

main();

// deploy.js - CI/CD deployment automation script
const { exec } = require('child_process');
const shlex = require('shlex');
const fs = require('fs');

function getBranchName() {
  // Read branch from git config file (simulating external input)
  try {
    const config = fs.readFileSync('.git/config', 'utf8');
    const match = config.match(/\[branch "([^"]+)"\]/);
    return match ? match[1] : 'main';
  } catch {
    return 'main';
  }
}

function deployVulnerable() {
  const branch = getBranchName();
  // VULNERABILITY: branch name concatenated into shell command with shell:true
  const cmd = `git pull origin ${branch} && npm run build && pm2 restart app`;
  exec(cmd, { shell: true }, (err, stdout, stderr) => {
    if (err) console.error(`Deploy failed: ${stderr}`);
    else console.log(`Deploy OK: ${stdout}`);
  });
}

function deploySafe() {
  const branch = getBranchName();
  // SAFE: using execFile with argument array, no shell interpretation
  const { execFile } = require('child_process');
  execFile('git', ['pull', 'origin', branch], { shell: false }, (err, stdout, stderr) => {
    if (err) {
      console.error(`Git pull failed: ${stderr}`);
      return;
    }
    // After successful pull, run build and restart (still using execFile)
    execFile('npm', ['run', 'build'], { shell: false }, (err2) => {
      if (err2) {
        console.error(`Build failed: ${err2.message}`);
        return;
      }
      execFile('pm2', ['restart', 'app'], { shell: false }, (err3) => {
        if (err3) console.error(`Restart failed: ${err3.message}`);
        else console.log('Deploy OK');
      });
    });
  });
}

// Main entry - choose which deploy function to run
const mode = process.env.DEPLOY_MODE || 'safe';
if (mode === 'vuln') {
  deployVulnerable();
} else {
